// ❌ 悪い例（パディングが多く発生しサイズが大きくなる）
struct BadStruct {
    char a;      // 1バイト
    // 3バイトのパディング
    int b;       // 4バイト
    char c;      // 1バイト
    // 3バイトのパディング
}; // 合計: 12バイト

// ✅ 良い例（大きい型から順に並べることでパディングを最小化）
struct GoodStruct {
    int b;       // 4バイト
    char a;      // 1バイト
    char c;      // 1バイト
    // 2バイトのパディング
}; // 合計: 8バイト

// 複数のフラグを個別の変数で持つと最低でも数バイト消費する
// ビットフィールドを使えば1バイトに綺麗に収まる
struct SystemStatus {
    uint8_t is_running : 1;
    uint8_t has_error  : 1;
    uint8_t mode       : 2; // 0~3の値
    uint8_t reserved   : 4; // 将来の拡張用
}; // 合計: 1バイト
